import java.util.*;
import java.io.*;

public class tr0_variant1 {
    static final int MOD = 998244353;
    static final long INF = (long) 1e18 + 1;

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();

        if (k >= n) {
            System.out.println(0);
            return;
        }

        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 0; i < n; i++) {
            fact[i + 1] = (i + 1) * fact[i] % MOD;
        }

        if (k == 0) {
            System.out.println(fact[n]);
            return;
        }

        int c = n - (int) k;
        long ans = fact[n];
        ans = ans * modPow(fact[c], MOD - 2) % MOD;
        ans = ans * modPow(fact[n - c], MOD - 2) % MOD;

        long sum = 0;
        for (int i = 0; i <= c; i++) {
            long term = fact[c] * modPow(fact[i], MOD - 2) % MOD;
            term = term * modPow(fact[c - i], MOD - 2) % MOD;
            term = term * modPow(c - i, n) % MOD;
            if (i % 2 == 0) {
                sum = (sum + term) % MOD;
            } else {
                sum = (sum - term + MOD) % MOD;
            }
        }

        ans = ans * sum % MOD * 2 % MOD;
        System.out.println(ans);
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static class Scanner {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public Scanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public Scanner(String filename) throws IOException {
            reader = new BufferedReader(new FileReader(filename));
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public String next() throws IOException {
            return nextToken();
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        public char nextChar() throws IOException {
            return nextToken().charAt(0);
        }

        public long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        public int[] nextIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public long[] nextLongArray(int size) throws IOException {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        public boolean ready() throws IOException {
            return reader.ready();
        }

        public void sleep(long ms) throws InterruptedException {
            Thread.sleep(ms);
        }
    }
